elif kind=='ids' and re.fullmatch(r'[0-9]+-[0-9]+',arg):
    first,last=map(int,arg.split('-'))
    if first>last:sys.exit('ids: first is after last')
    where=f'id between {first} and {last}';name=f'customers-{first}-{last}';what=f'ids={first}-{last}'
else:sys.exit('invalid export request')
