except FileExistsError:sys.exit('export file exists; retry in one second')
with os.fdopen(fd,'w') as f:csv.writer(f,lineterminator='\n').writerows(rows)
n=max(0,len(rows)-1)
log.write(f'{stamp.isoformat(timespec="seconds")} user={who} {what} rows={n} out={out}\n');log.close()
print(f'{n} rows in {out}')
